const MAX_RECORDING_MS = 60_000;
let activeRecording: ExpoRecording | null = null;
let autoStopTimer: ReturnType<typeof setTimeout> | null = null;
let finalizingPromise: Promise<RecordingResult> | null = null;
let completedResult: RecordingResult | null = null;

function getAudio(): ExpoAudioModule {
  return (require('expo-av') as { Audio: ExpoAudioModule }).Audio;
}

function clearAutoStopTimer(): void {
  if (autoStopTimer) {
    clearTimeout(autoStopTimer);
    autoStopTimer = null;
  }
}

async function resetAudioMode(): Promise<void> {
  try {
    await getAudio().setAudioModeAsync({ allowsRecordingIOS: false });
  } catch {
    // A recording result must not be lost because restoring the audio mode failed.
  }
}

function beginFinalize(): Promise<RecordingResult> {
  if (finalizingPromise) return finalizingPromise;
  if (!activeRecording) {
    if (completedResult) return Promise.resolve(completedResult);
    return Promise.reject(new Error('No audio recording is active'));
  }

  const recording = activeRecording;
  activeRecording = null;
  clearAutoStopTimer();
  const promise = (async () => {
    const status = await recording.getStatusAsync();
    await recording.stopAndUnloadAsync();
    const uri = recording.getURI();
    if (!uri) throw new Error('The audio recording did not produce a file');
    return {
      uri,
      durationMs: Math.min(status.durationMillis ?? 0, MAX_RECORDING_MS),
    };
  })().finally(resetAudioMode);

  finalizingPromise = promise;
  void promise.finally(() => {
    if (finalizingPromise === promise) finalizingPromise = null;
  });
  return promise;
}

export async function requestPermissions(): Promise<boolean> {
  const permission = await getAudio().requestPermissionsAsync();
  return permission.granted;
}

export async function startRecording(): Promise<void> {
  if (activeRecording || finalizingPromise) {
    throw new Error('An audio recording is already active');
  }

  completedResult = null;
  const Audio = getAudio();
  await Audio.setAudioModeAsync({
    allowsRecordingIOS: true,
    playsInSilentModeIOS: true,
  });
  const recording = new Audio.Recording();
  try {
    await recording.prepareToRecordAsync(Audio.Recording.RecordingOptionsPresets.HIGH_QUALITY);
    await recording.startAsync();
    activeRecording = recording;
    autoStopTimer = setTimeout(() => {
      void beginFinalize()
        .then((result) => {
          completedResult = result;
        })
        .catch(() => {
          completedResult = null;
        });
    }, MAX_RECORDING_MS);
  } catch (error) {
    await resetAudioMode();
    throw error;
  }
}

export async function stopRecording(): Promise<RecordingResult> {
  if (completedResult) {
    const result = completedResult;
    completedResult = null;
    return result;
  }
  const result = await beginFinalize();
  completedResult = null;
  return result;
}

export async function cancelRecording(): Promise<void> {
  completedResult = null;
  clearAutoStopTimer();
  if (finalizingPromise) {
    try {
      await finalizingPromise;
    } catch {
      // Cancellation intentionally discards finalization errors.
    }
    completedResult = null;
    return;
